// Matrix class implementation

class Matrix {
  constructor(rows) {
    // Check if rows is an array
    if (!Array.isArray(rows)) {
      throw new Error("Rows must be an array");
    }

    // Check if there are no rows
    if (rows.length === 0) {
      throw new Error("Matrix must have at least one row");
    }

    // Check each row
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];

      // Check if row is an array
      if (!Array.isArray(row)) {
        throw new Error("Each row must be an array");
      }

      // Check if row is empty
      if (row.length === 0) {
        throw new Error("Rows must not be empty");
      }

      // Check if all elements in the row are finite numbers
      for (let j = 0; j < row.length; j++) {
        if (typeof row[j] !== 'number' || !isFinite(row[j])) {
          throw new Error("All elements must be finite numbers");
        }
      }

      // Check if all rows have the same length
      if (i > 0 && row.length !== rows[0].length) {
        throw new Error("All rows must have the same length");
      }
    }

    this._rows = rows;
  }

  shape() {
    return [this._rows.length, this._rows[0].length];
  }

  get(r, c) {
    // Check bounds
    if (r < 0 || r >= this._rows.length || c < 0 || c >= this._rows[0].length) {
      throw new Error("Index out of bounds");
    }

    return this._rows[r][c];
  }

  toArray() {
    // Return a copy of the rows
    return this._rows.map(row => [...row]);
  }
}

// Asserts that all pass
function runAsserts() {
